&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de druide&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_druide_0&quot; href=&quot;#Les_arch&#233;types_de_druide_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Ondin-(Druide).html&quot; title=&quot;Adepte ondin&quot;&gt;Adepte ondin&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;Ondin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ami-Des-F&#233;es-(Druide).html&quot; title=&quot;Ami des f&#233;es&quot;&gt;Ami des f&#233;es&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arpenteur-De-Monde-(Druide).html&quot; title=&quot;Arpenteur de monde&quot;&gt;Arpenteur de monde&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspirant-Naga-(Druide).html&quot; title=&quot;Aspirant naga&quot;&gt;Aspirant naga&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nagaji-(Race).html&quot; title=&quot;Les nagajis&quot;&gt;nagaji&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chamanes-Animaux-(Druide).html&quot; title=&quot;Chamanes animaux&quot;&gt;Chamanes animaux&lt;/a&gt; (MJRA,AG,AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changepeau-(Druide).html&quot; title=&quot;Changepeau&quot;&gt;Changepeau&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html&quot; title=&quot;Chanteur sylvestre&quot;&gt;Chanteur sylvestre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chuchoteur-Sauvage-(Druide).html&quot; title=&quot;Chuchoteur sauvage&quot;&gt;Chuchoteur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croc-De-La-Nature-(Druide).html&quot; title=&quot;Croc de la nature&quot;&gt;Croc de la nature&lt;/a&gt; (MCA) &lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Aquatique-(Druide).html&quot; title=&quot;Druide aquatique&quot;&gt;Druide aquatique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Arctique-(Druide).html&quot; title=&quot;Druide arctique&quot;&gt;Druide arctique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-De-La-Jungle-(Druide).html&quot; title=&quot;Druide de la jungle&quot;&gt;Druide de la jungle&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Cavernes-(Druide).html&quot; title=&quot;Druide des cavernes&quot;&gt;Druide des cavernes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-D&#233;serts-(Druide).html&quot; title=&quot;Druide des d&#233;serts&quot;&gt;Druide des d&#233;serts&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Marais-(Druide).html&quot; title=&quot;Druide des marais&quot;&gt;Druide des marais&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Montagnes-(Druide).html&quot; title=&quot;Druide des montagnes&quot;&gt;Druide des montagnes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Ouragans-(Druide).html&quot; title=&quot;Druide des ouragans&quot;&gt;Druide des ouragans&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Plaines-(Druide).html&quot; title=&quot;Druide des plaines&quot;&gt;Druide des plaines&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Temp&#234;tes-(Druide).html&quot; title=&quot;Druide des temp&#234;tes&quot;&gt;Druide des temp&#234;tes&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Du-Ciel-(Druide).html&quot; title=&quot;Druide du ciel&quot;&gt;Druide du ciel&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;Sylphe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-R&#233;incarn&#233;-(Druide).html&quot; title=&quot;Druide r&#233;incarn&#233;&quot;&gt;Druide r&#233;incarn&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Urbain-(Druide).html&quot; title=&quot;Druide urbain&quot;&gt;Druide urbain&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-De-La-Lune-(Druide).html&quot; title=&quot;Enfant de la lune&quot;&gt;Enfant de la lune&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-Sauvage-(Druide).html&quot; title=&quot;Enfant sauvage&quot;&gt;Enfant sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;trisseur-(Druide).html&quot; title=&quot;Fl&#233;trisseur&quot;&gt;Fl&#233;trisseur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Antique-(Druide).html&quot; title=&quot;Gardien antique&quot;&gt;Gardien antique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;Homme-serpent&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-Sauvage-(Druide).html&quot; title=&quot;M&#233;tamorphe sauvage&quot;&gt;M&#233;tamorphe sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Des-Menhirs-(Druide).html&quot; title=&quot;Sage des menhirs&quot;&gt;Sage des menhirs&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-La-Meute-(Druide).html&quot; title=&quot;Seigneur de la meute&quot;&gt;Seigneur de la meute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Surnaturaliste-(Druide).html&quot; title=&quot;Surnaturaliste&quot;&gt;Surnaturaliste&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Troll-Furieux-(Druide).html&quot; title=&quot;Troll furieux&quot;&gt;Troll furieux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;Troll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Urushiol-(Druide).html&quot; title=&quot;Urushiol&quot;&gt;Urushiol&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Origines occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Origins/Origines occultes ; /!\ Traduit par la communaut&#233; /!\&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOO.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Les surnaturalistes assimilent les ph&#233;nom&#232;nes paranormaux &#224; des extensions de la nature.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes et Armures&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_et_Armures_0&quot; href=&quot;#Armes_et_Armures_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un surnaturaliste n&#39;est form&#233; au port d&#39;aucune armure. Cela modifie les formations au maniement des armes et au port des armures du druide.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Botaniste &#233;trange (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Botaniste_&#233;trange_Ext_1&quot; href=&quot;#Botaniste_&#233;trange_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un surnaturaliste peut cibler les plantes avec les effets mentaux qu&#39;il cr&#233;e et avec les sorts qui devraient normalement affecter les animaux. Un tel sort qui autorise un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; peut &#224; la place &#234;tre annul&#233; par la plante cibl&#233;e avec un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; au m&#234;me &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt;. Il peut &#233;galement choisir les capacit&#233;s &lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html#Lien_avec_les_plantes_Ext_0&quot; title=&quot;Chanteur sylvestre&quot;&gt;lien avec les plantes&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html#Empathie_avec_la_verdure_Ext_1&quot; title=&quot;Chanteur sylvestre&quot;&gt;empathie avec la verdure&lt;/a&gt;, comme un chanteur sylvestre, &#224; la place de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#PACTEAVECLANATURE&quot; title=&quot;Le druide&quot;&gt;pacte avec la nature&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#EMPATHIESAUVAGE&quot; title=&quot;Le druide&quot;&gt;empathie sauvage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;&#201;rudit du paranormal (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;rudit_du_paranormal_Ext_2&quot; href=&quot;#&#201;rudit_du_paranormal_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un surnaturaliste obtient &lt;a class=&quot;pagelink&quot; href=&quot;Sensibilit&#233;-Psychique.html&quot; title=&quot;Sensibilit&#233; psychique&quot;&gt;Sensibilit&#233; psychique&lt;/a&gt; comme don suppl&#233;mentaire et ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res), &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe. Au niveau 3 et tous les 3 niveaux par la suite, il peut s&#233;lectionner un sort de la &lt;a class=&quot;pagelink&quot; href=&quot;Sorts-De-Psychiste.html&quot; title=&quot;Liste des sorts de psychiste&quot;&gt;liste des sorts de psychiste&lt;/a&gt; et l&#39;ajouter &#224; sa liste de sorts de druide, et peut le pr&#233;parer et le lancer comme un sort de druide. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#INSTINCTNATUREL&quot; title=&quot;Le druide&quot;&gt;instinct naturel&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#ABSENCEDETRACES&quot; title=&quot;Le druide&quot;&gt;absence de traces&lt;/a&gt;, et &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#RESISTANCEALAPPELDELANATURE&quot; title=&quot;Le druide&quot;&gt;r&#233;sistance &#224; l&#39;appel de la nature&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Esprit animal (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Esprit_animal_Sur_3&quot; href=&quot;#Esprit_animal_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, un surnaturaliste peut effectuer des s&#233;ances m&#233;diumniques pour appeler un esprit animal de n&#39;importe quel animal avec lequel il est familier pour qu&#39;il lui serve de compagnon et de guide. Le surnaturaliste gagne les capacit&#233;s &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#ESPRIT&quot; title=&quot;Le m&#233;dium&quot;&gt;esprit&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#BONUSSPIRITUEL&quot; title=&quot;Le m&#233;dium&quot;&gt;bonus spirituel&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#ACC&#200;SDEPUISSANCESPIRITUELLE&quot; title=&quot;Le m&#233;dium&quot;&gt;acc&#232;s de puissance spirituelle&lt;/a&gt;, et &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#TABOU&quot; title=&quot;Le m&#233;dium&quot;&gt;tabou&lt;/a&gt; comme un m&#233;dium avec 3 niveaux de moins que son niveau de druide. Les alli&#233;s du surnaturaliste ne peuvent pas participer &#224; cette s&#233;ance. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#FORMANIMALE&quot; title=&quot;Le druide&quot;&gt;forme animale&lt;/a&gt;. Les capacit&#233;s de l&#39;esprit animal sont d&#233;crites ci-dessous.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Bonus spirituel.&lt;/b&gt; Le bonus spirituel du personnage s&#39;applique aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; de ses armes naturelles et aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt; en relation avec les animaux et les plantes.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Aubaine de s&#233;ance m&#233;diumnique.&lt;/b&gt; Le bonus d&#39;armure naturelle &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; du personnage est augment&#233; de 1.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Sites de pr&#233;dilection.&lt;/b&gt; Environnement de pr&#233;dilection de l&#39;animal invoqu&#233;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Malus d&#39;influence.&lt;/b&gt; Le personnage devient sauvage et f&#233;roce, et subit un malus &#233;gal &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#BONUSSPIRITUEL&quot; title=&quot;Le m&#233;dium&quot;&gt;bonus spirituel&lt;/a&gt; aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;, aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; et d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; ainsi qu&#39;aux tests de comp&#233;tence bas&#233;s sur ces caract&#233;ristiques.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Tabous.&lt;/b&gt; Le personnage choisit l&#39;un des tabous suivants :
&lt;ul&gt;&lt;li&gt;il ne peut pas parler (sauf avec les animaux et les plantes) ;&lt;/li&gt;&lt;li&gt;il ne doit pas manier d&#39;armes manufactur&#233;es ;&lt;/li&gt;&lt;li&gt;il lui est interdit de manger quelque chose qu&#39;il n&#39;a pas lui-m&#234;me tu&#233; ou r&#233;colt&#233;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;b&gt;Transformation tot&#233;mique (mineur, Sur).&lt;/b&gt; Le personnage gagne toutes les capacit&#233;s d&#233;crites ici et poss&#233;d&#233;es par l&#39;animal dont il a invoqu&#233; l&#39;esprit: morsure (1d6 pour un druide de taille M), 2 griffes (1d4 pour un druide de taille M), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt;, am&#233;lioration de la vitesse de base (bonus d&#39;am&#233;lioration de +6m &#224; la vitesse de base du druide), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;Odorat (Ext)&quot;&gt;odorat&lt;/a&gt;, et vitesse de nage (9m).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Chef de meute (interm&#233;diaire, Sur).&lt;/b&gt; Lorsque le personnage &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Convocation.html&quot; title=&quot;Convocation&quot;&gt;convoque&lt;/a&gt; des animaux semblables &#224; son esprit animal, ils gagnent un bonus de +2 &#224; leurs &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; et &#224; leurs &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Frappe sauvage (majeur, Sur).&lt;/b&gt; Le personnage peut autoriser son esprit animal &#224; prendre 1 point d&#39;influence sur lui par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; pour autoriser une plante ou un animal (y compris son compagnon) dans un rayon de 9 m qui peut le voir et l&#39;entendre &#224; imm&#233;diatement effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Cœur sauvage (supr&#234;me, Ext).&lt;/b&gt; Le personnage obtient un bonus de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Enchantement.html&quot; title=&quot;Enchantement&quot;&gt;enchantement&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;effets mentaux&lt;/a&gt;, ainsi qu&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Immunit&#233;-(Capacit&#233;).html&quot; title=&quot;Immunit&#233; (Ext ou Sur)&quot;&gt;immunit&#233;&lt;/a&gt; contre les effets qui touchent uniquement les humano&#239;des. Une fois par jour, il peut lancer spontan&#233;ment n&#39;importe quel sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Dalli&#233;s-Naturels.html&quot; title=&quot;Convocation d&amp;#39;alli&#233;s naturels&quot;&gt;convocation d&#39;alli&#233;s naturels&lt;/a&gt;&lt;/i&gt; qu&#39;il est capable de lancer par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; sans d&#233;penser d&#39;emplacement de sort.
